var builder = WebApplication.CreateBuilder(args); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(); var app = builder.Build(); app.UseSwagger(); app.UseSwaggerUI();
var assets = new List<Asset>{new(1,"MacBook Pro 14","Laptop","Available"),new(2,"Sony A7 Camera","Camera","Booked"),new(3,"Meeting Room Kit","Equipment","Available")}; var bookings=new List<Booking>{new(1,2,"Maya Patel","2026-10-18","2026-10-20")};
app.MapGet("/api/health",()=>Results.Ok(new{service="AssetBooking API",status="healthy",checkedAt=DateTime.UtcNow})); app.MapGet("/api/assets",(string? type,string? status)=>Results.Ok(assets.Where(a=>(type==null||a.Type.Equals(type,StringComparison.OrdinalIgnoreCase))&&(status==null||a.Status.Equals(status,StringComparison.OrdinalIgnoreCase))))); app.MapGet("/api/bookings",()=>Results.Ok(bookings));
app.MapPost("/api/bookings",(CreateBooking request)=>{if(!assets.Any(a=>a.Id==request.AssetId))return Results.NotFound(new{error="Asset not found"});if(bookings.Any(b=>b.AssetId==request.AssetId&&DatesOverlap(b.Start,b.End,request.Start,request.End)))return Results.Conflict(new{error="Asset is already booked for those dates"});var booking=new Booking(bookings.Count+1,request.AssetId,request.BookedBy,request.Start,request.End);bookings.Add(booking);var asset=assets.First(a=>a.Id==request.AssetId);assets[assets.IndexOf(asset)]=asset with{Status="Booked"};return Results.Created($"/api/bookings/{booking.Id}",booking);}); app.MapDelete("/api/bookings/{id:int}",(int id)=>{var booking=bookings.FirstOrDefault(b=>b.Id==id);if(booking==null)return Results.NotFound();bookings.Remove(booking);return Results.NoContent();}); app.Run();
static bool DatesOverlap(string a,string b,string c,string d)=>DateTime.Parse(a)<=DateTime.Parse(d)&&DateTime.Parse(c)<=DateTime.Parse(b); record Asset(int Id,string Name,string Type,string Status); record Booking(int Id,int AssetId,string BookedBy,string Start,string End); record CreateBooking(int AssetId,string BookedBy,string Start,string End);
